import numpy as np
def max_pool2d(image, pool_size):
    image = np.asarray(image, float); H, W = image.shape
    oh, ow = H // pool_size, W // pool_size
    out = np.zeros((oh, ow))
    for i in range(oh):
        for j in range(ow):
            out[i, j] = image[i*pool_size:(i+1)*pool_size, j*pool_size:(j+1)*pool_size].max()
    return out

import numpy as np
def bert_mlm_loss(logits, targets, mask_indices):
    logits = np.asarray(logits, float); targets = np.asarray(targets); mask = np.asarray(mask_indices)
    idx = np.where(mask == 1)[0]
    if idx.size == 0:
        return 0.0
    z = logits[idx]; z = z - z.max(axis=1, keepdims=True)
    logp = z - np.log(np.exp(z).sum(axis=1, keepdims=True))
    return float(-logp[np.arange(idx.size), targets[idx]].mean())

import numpy as np
def vit_patch_embed(image, patch_size, W):
    image = np.asarray(image, float); W = np.asarray(W, float)
    H, Wd, C = image.shape; p = patch_size
    patches = []
    for i in range(0, H, p):
        for j in range(0, Wd, p):
            patches.append(image[i:i+p, j:j+p, :].reshape(-1))
    return np.stack(patches) @ W
